import React, { useEffect, useState } from 'react';
import { Card, Typography, Input, Space, Button, Checkbox, Alert, message, Select } from 'antd';
import { api } from '../api';

const Register: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [pending, setPending] = useState(false);
  const [privacyUrl, setPrivacyUrl] = useState<string | null>(null);
  const [securityUrl, setSecurityUrl] = useState<string | null>(null);
  const [consentPersonal, setConsentPersonal] = useState(false);
  const [consentSecurity, setConsentSecurity] = useState(false);
  const [comment, setComment] = useState('');
  const [promoCode, setPromoCode] = useState('');
  const [desiredRole, setDesiredRole] = useState<string | undefined>(undefined);
  const [desiredPlan, setDesiredPlan] = useState<string | undefined>(undefined);
  const [error, setError] = useState<string | null>(null);

  const loadStatus = async () => {
    try {
      setLoading(true);
      setError(null);
      const resp = await api('/registration/status');
      if (resp?.status === 'success') {
        setPending(Boolean(resp.pending));
        setPrivacyUrl(resp.documents?.privacy_url || null);
        setSecurityUrl(resp.documents?.security_url || null);
      }
    } catch (e: any) {
      setError(e?.message || 'Ошибка загрузки статуса');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadStatus();
  }, []);

  const canSubmit = consentPersonal && consentSecurity;

  const handleRedeemPromo = async () => {
    if (!canSubmit) {
      message.warning('Подтвердите согласия перед продолжением');
      return;
    }
    if (!promoCode.trim()) {
      message.warning('Введите промокод');
      return;
    }
    try {
      setError(null);
      const resp = await api('/registration/promo-redeem', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code: promoCode.trim(), comment, consent_personal: consentPersonal, consent_security: consentSecurity })
      });
      if (resp?.status === 'success') {
        message.success('Промокод активирован');
        // после активации роль start снята — обновим статус
        await loadStatus();
      }
    } catch (e: any) {
      setError(e?.message || 'Ошибка активации промокода');
    }
  };

  const handleSendRequest = async () => {
    if (!canSubmit) {
      message.warning('Подтвердите согласия перед продолжением');
      return;
    }
    try {
      setError(null);
      const resp = await api('/registration/request', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ comment, desired_role: desiredRole, desired_plan: desiredPlan, consent_personal: consentPersonal, consent_security: consentSecurity })
      });
      if (resp?.status === 'success') {
        message.success('Заявка отправлена. Мы уведомим вас после подтверждения.');
      }
    } catch (e: any) {
      setError(e?.message || 'Ошибка отправки заявки');
    }
  };

  return (
    <div style={{ padding: 16 }}>
      <Card loading={loading}>
        <Typography.Title level={3}>Регистрация</Typography.Title>
        <Typography.Paragraph>
          Добро пожаловать в SoulPulse. Перед началом работы подтвердите согласия и выберите способ регистрации.
        </Typography.Paragraph>

        {error && <Alert type="error" showIcon style={{ marginBottom: 12 }} message={error} />}

        <Space direction="vertical" style={{ width: '100%' }} size="middle">
          <div>
            <Checkbox checked={consentPersonal} onChange={(e) => setConsentPersonal(e.target.checked)}>
              Согласен на обработку персональных данных {privacyUrl ? (<a href={privacyUrl} target="_blank" rel="noreferrer">(прочитать)</a>) : null}
            </Checkbox>
          </div>
          <div>
            <Checkbox checked={consentSecurity} onChange={(e) => setConsentSecurity(e.target.checked)}>
              Согласен с политикой безопасности приложения {securityUrl ? (<a href={securityUrl} target="_blank" rel="noreferrer">(прочитать)</a>) : null}
            </Checkbox>
          </div>

          <Input.TextArea rows={3} placeholder="О себе (необязательно)" value={comment} onChange={(e) => setComment(e.target.value)} />

          <Space.Compact style={{ width: '100%' }}>
            <Select
              style={{ minWidth: 160 }}
              placeholder="Желаемая роль"
              value={desiredRole}
              onChange={setDesiredRole}
              allowClear
              options={[
                { label: 'Basic', value: 'basic' },
                { label: 'Premium', value: 'premium' },
                { label: 'VIP', value: 'vip' },
              ]}
            />
            <Select
              style={{ minWidth: 160 }}
              placeholder="Тарифный план"
              value={desiredPlan}
              onChange={setDesiredPlan}
              allowClear
              options={[
                { label: 'Basic', value: 'basic' },
                { label: 'Premium', value: 'premium' },
                { label: 'VIP', value: 'vip' },
              ]}
            />
          </Space.Compact>

          <Space.Compact style={{ width: '100%' }}>
            <Input placeholder="Промокод (необязательно)" value={promoCode} onChange={(e) => setPromoCode(e.target.value)} />
            <Button type="primary" onClick={handleRedeemPromo} disabled={!canSubmit}>Активировать</Button>
          </Space.Compact>

          <div>
            <Button onClick={handleSendRequest} disabled={!canSubmit}>Отправить заявку на регистрацию</Button>
          </div>
        </Space>

        {!pending && (
          <Alert style={{ marginTop: 12 }} type="success" showIcon message="Регистрация завершена. Вы можете пользоваться приложением." />
        )}
      </Card>
    </div>
  );
};

export default Register;


